import {slerp} from './keyframes.js';
export function validateSpeeds(project){const segments=project.speedSegments||[],ids=new Set();if(!Array.isArray(segments)||segments.length>64)throw Error('배속 구간은 64개까지 지원합니다.');let end=0;for(const s of [...segments].sort((a,b)=>a.time-b.time)){if(!/^s[1-9]\d{0,5}$/.test(s.id)||ids.has(s.id)||![s.time,s.duration,s.rate].every(Number.isFinite)||s.time<0||s.duration<.05||s.time+s.duration>project.duration+1e-8||s.rate<.1||s.rate>16||s.time<end-1e-8)throw Error('배속 구간이 겹치거나 범위를 벗어났습니다.');ids.add(s.id);end=s.time+s.duration;}}
export function createTimeMap(project,duration=project.duration){const spans=[];let source=0,output=0;const add=(end,rate)=>{end=Math.min(duration,end);if(end<=source)return;const span={start:source,end,rate,outputStart:output,outputEnd:output+(end-source)/rate};spans.push(span);source=end;output=span.outputEnd;};for(const s of [...(project.speedSegments||[])].sort((a,b)=>a.time-b.time)){if(s.time>=duration)break;add(s.time,1);add(s.time+s.duration,s.rate);}add(duration,1);return {duration:output,spans,toOutput(t){t=Math.max(0,Math.min(duration,t));const s=spans.find(s=>t<=s.end)||spans.at(-1);return s?s.outputStart+(t-s.start)/s.rate:0;},toSource(t){t=Math.max(0,Math.min(output,t));const s=spans.find(s=>t<=s.outputEnd)||spans.at(-1);return s?s.start+(t-s.outputStart)*s.rate:0;}};}
export function retimeRecording(project,recording){if(!(project.speedSegments||[]).some(s=>s.rate!==1))return recording;const map=createTimeMap(project,recording.duration),ticks=Math.max(1,Math.ceil(map.duration*20-1e-8));if((ticks+1)*(64+recording.objects.length*168)>512*1024*1024)throw Error('배속 적용 후 프레임이 너무 많습니다. 구간 길이나 감속 정도를 줄여 주세요.');const frames=Array.from({length:ticks+1},(_,tick)=>{const source=map.toSource(tick/20)*20,lo=Math.min(recording.ticks,Math.floor(source)),hi=Math.min(recording.ticks,lo+1),t=source-lo;return recording.frames[lo].map((a,i)=>{const b=recording.frames[hi][i];if(a===b)return a;return {...a,p:a.p.map((v,j)=>v+(b.p[j]-v)*t),q:slerp(a.q,b.q,t),...(a.size&&b.size?{size:a.size.map((v,j)=>v+(b.size[j]-v)*t)}:{})};});});return {...recording,frames,ticks,duration:ticks/20,sourceDuration:recording.duration,timeMap:map,fractures:(recording.fractures||[]).map(f=>({...f,time:map.toOutput(f.time)}))};}
